package com.hms.notifications;
import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/notifications") public class NotificationController { private final TenantRepository tenants; private final NotificationMessageRepository messages; public NotificationController(TenantRepository t,NotificationMessageRepository m){tenants=t;messages=m;} @GetMapping public List<NotificationMessage> list(@PathVariable String tenantSlug){return messages.findAllByTenantIdOrderByCreatedAtDesc(tenant(tenantSlug));} @PostMapping @ResponseStatus(HttpStatus.CREATED) public NotificationMessage queue(@PathVariable String tenantSlug,@Valid @RequestBody CreateNotificationRequest r){return messages.save(new NotificationMessage(tenant(tenantSlug),r));} private UUID tenant(String s){return tenants.findBySlug(s).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(s));} }
